package com.nextfeet.nextfeet.repository; import java.util.*; import java.sql.*; import org.springframework.jdbc.core.*; import org.springframework.jdbc.support.GeneratedKeyHolder; import org.springframework.jdbc.support.KeyHolder; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Pedido; @Repository public class PedidoRepository implements PedidoDAO {private final JdbcTemplate db; public PedidoRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Pedido> map=(r,n)->{Pedido p=new Pedido();p.setId(r.getInt("id"));p.setCodigo(r.getString("codigo"));p.setUsuarioId(r.getInt("usuario_id"));p.setDireccionId((Integer)r.getObject("direccion_id"));p.setFecha(r.getTimestamp("fecha").toLocalDateTime());p.setTotal(r.getBigDecimal("total"));p.setEstado(r.getString("estado"));p.setMetodoPago(r.getString("metodo_pago"));p.setMotivoAnulacion(r.getString("motivo_anulacion"));return p;}; public List<Pedido> listarPorUsuario(Integer id){return db.query("select * from pedido where usuario_id=? order by fecha desc",map,id);} public List<Pedido> listarTodos(){return db.query("select * from pedido order by fecha desc",map);} public Pedido obtener(Integer id){return db.query("select * from pedido where id=?",map,id).stream().findFirst().orElse(null);} public Integer crear(Pedido p){KeyHolder kh=new GeneratedKeyHolder();db.update(c->{PreparedStatement s=c.prepareStatement("insert into pedido(codigo,usuario_id,direccion_id,total,estado,metodo_pago) values(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setString(1,p.getCodigo());s.setInt(2,p.getUsuarioId());s.setObject(3,p.getDireccionId());s.setBigDecimal(4,p.getTotal());s.setString(5,p.getEstado());s.setString(6,p.getMetodoPago());return s;},kh);return kh.getKey().intValue();} public void actualizarEstado(Integer id,String e){db.update("update pedido set estado=? where id=?",e,id);} public void anular(Integer id,String m){db.update("update pedido set estado='ANULADO',motivo_anulacion=? where id=?",m,id);} public void agregarDetalle(Integer p,Integer z,String t,int c,java.math.BigDecimal pr){db.update("insert into detalle_pedido(pedido_id,zapatilla_id,talla,cantidad,precio_unitario,subtotal) values(?,?,?,?,?,?)",p,z,t,c,pr,pr.multiply(java.math.BigDecimal.valueOf(c)));} }